  "what the retrieved evidence establishes for this question"
 ],
 "evidence_does_not_establish": [
  "what it leaves open or cannot show"
 ],
 "own_inferences": [
  "your inference, not stated in any record"
 ],
 "uncertainties": [
  "uncertainty or missing information"
 ],
 "historical_effect": {
  "changed_decision": "yes | no | no_historical_evidence",
  "explanation": "whether and how the historical evidence changed the decision"
 },
 "testability": {
  "p_testable": "number in [0,1]: probability the question can be answered with the stated data at useful power",
  "blocking_constraints": [
   {
    "code": "one of RISK_CODES",
    "text": "string"
   }
  ]
 },
 "prior_work": {
  "already_answered": "yes | partly | no | unknown",
  "cited": [
   "identifiers of prior work relied on"
  ],
  "summary": "string"
 },
 "risks": [
  {
   "code": "one of RISK_CODES",
   "text": "string"
  }
 ],
 "predicted_outcome": {
  "supported": "probability",
  "rejected": "probability",
  "untestable": "probability",
  "artifact": "probability",
  "uncertain": "probability"
 },
 "decision": "proceed | proceed_with_changes | do_not_proceed",
 "design": {
  "estimand": "string",
  "unit": "string",
  "sample": "string",
  "power": "string",
  "controls": "string",
  "falsification": "string",
  "multiplicity": "string",
  "decision_rule": "string",
  "data_version": "string"
 }
}
Field guidance:
- historical_evidence and failed_approaches: only records returned by a tool, with the status as recorded; empty lists
  if nothing relevant was returned.
- testability.p_testable: probability that the question can be answered with the stated data at useful statistical power.
- prior_work.already_answered: whether retrieved earlier work already answered substantially the same question.
  Use "unknown" if no earlier work was retrieved. List identifiers you relied on in prior_work.cited.
- predicted_outcome: probabilities (summing to 1) of what a competent test of the question as posed would conclude:
  supported, rejected (adequately powered null), untestable (cannot be tested with this data), artifact (apparent
  effect produced by a flaw), uncertain (inconclusive or inadequately tested).
- decision: proceed, proceed_with_changes (state the changes in design), or do_not_proceed.
- design: a pre-registration-quality plan even if the decision is do_not_proceed (then describe the minimum viable test).

{"action": "final", "output": {
  "research_concepts": [
    "cut-heavy shapers: players with low usage, positive residual structural influence, and high share of possessions initiated via CUT play type",
    "drive-heavy shapers: players with low usage, positive residual structural influence, and high share of possessions initiated via DRIVE play type",
    "role portability: the extent to which a shaper's structural influence on teammates' play-type mix is reproduced after changing teams",
    "shaper classification from play-type initiation records: using usage, structural influence residuals, and initiation diet shares",
    "connector cut vs drive portability as a closely related construct",
    "small sample of shaper movers (n=24) across 2022-26 NBA data"
  ],
  "methodological_questions": [
    "How to define cut-heavy vs drive-heavy among shapers from play-type initiation data?",
    "What metric captures whether a shaper's organizational function 'travels' to a new team?",
    "Can portability be measured with only 24 movers at adequate statistical power?",
    "How to control for destination team system, usage change, and role redefinition?",
    "Is the shaper sample large enough to avoid the underpowered failures seen in other connector-focused mover studies (e.g., FAM:SF-APPS-090, FAM:SF-APPS-024)?"
  ],
  "historical_evidence": [
    {
      "id": "FAM:SF-CHT-057",
      "status_as_recorded": "supported",
      "finding": "Pre-move cut share predicted connector portability: cut share rho=+0.265 p=0.011 AUC 0.653; cut-drive rho=+0.314 p=0.002 AUC 0.656; drive share rho=-0.278 p=0.007. Top cut tercile 65% portable (median Delta +0.167), bottom 35% (median -0.039). LOO AUC 0.622, permutation p=0.005. n=92 connector movers."
    },
    {
      "id": "FAM:SF-APPS-090",
      "status_as_recorded": "untestable",
      "finding": "Connector diet-matching to destination structural gap was untestable due to small sample: 19 taxonomy connectors, match rate 15.7% leaving 5 matched. Binary delta p=0.156 (n=5/14)."
    },
    {
      "id": "FAM:SF-APPS-024",
      "status_as_recorded": "untestable",
      "finding": "DRIVE-as-BEST counter vs constrained mix was untestable: observed gap -0.066 PPP below MDE 0.180 PPP at 80% power (SD~0.34). n=44 could not distinguish a null from an effect up to 0.18 PPP."
    },
    {
      "id": "FAM:SF-PAP-029",
      "status_as_recorded": "untestable",
      "finding": "Destination net rating checks for movers were underpowered and null once corrected for landing-spot quality. Dropped from Paper 1; no numbers retained."
    }
  ],
  "failed_approaches": [
    {
      "id": "FAM:SF-APPS-090",
      "what_failed": "Diet-matching connectors to destination structural gaps to predict post-move outcomes",
      "why": "insufficient sample: only 19 connectors, match rate 15.7% produced 5 matched cases; continuous Spearman was null"
    },
    {
      "id": "FAM:SF-APPS-024",
      "what_failed": "Testing DRIVE-as-BEST counter effectiveness against a feasibility-constrained play-type mix",
      "why": "observed gap (-0.066 PPP) far below minimum detectable effect (0.180 PPP) with n=44; study could not distinguish true null from a meaningful effect"
    },
    {
      "id": "FAM:SF-PAP-029",
      "what_failed": "Linking mover portability to destination net-rating change",
      "why": "underpowered after correcting for landing-spot quality; no usable results"
    }
  ],
  "evidence_establishes": [
    "For connector movers (n=92), pre-move cut share positively predicts post-move portability (rho +0.265), while drive share negatively predicts it (rho -0.278), suggesting that cut-based organizational roles are more portable than drive-based ones in that population.",
    "Small-sample studies of player-level portability effects (n < ~40-50) often become untestable due to low power, even when a true effect exists, as seen in multiple project records."
  ],
  "evidence_does_not_establish": [
    "Whether the cut-vs-drive portability advantage holds specifically for shapers, as opposed to the broader connector population.",
    "The effect size for shapers or whether a sample of 24 shaper movers can reliably detect any difference.",
    "That the 24 available units are shapers according to the same operational definition used in earlier studies, or that the shaper classification is stable across seasons."
  ],
  "own_inferences": [
    "The research question is closely related to FAM:SF-CHT-057 but narrows to the shaper role; if shapers are a subset of connectors, the earlier finding raises prior plausibility.",
    "Given a projected sample of only 24 shapers, the study would almost certainly be underpowered to detect correlations of the magnitude observed in CHT-057 (rho ~0.26-0.31), analogous to failures in FAM:SF-APPS-090 and FAM:SF-APPS-024.",
    "Even if the true effect for shapers is larger, the small sample would produce wide confidence intervals and low replicability, making any conclusion unreliable."
  ],
  "uncertainties": [
    "The exact definition of 'shaper' used to select the 24 units (e.g., usage and residual influence thresholds, minimum games played, role classification pipeline version).",
    "The degree of overlap between shapers and the connector definition in FAM:SF-CHT-057.",
    "How portability is to be measured: change in structural influence, teammate play-type mix displacement, or reproduction of connector function.",
    "Whether the 24 units are the total number of shapers who changed teams in the data window, or a convenience sample with missing data."
  ],
  "historical_effect": {
    "changed_decision": "no",
    "explanation": "The historical evidence shows a positive result for a closely related population (connectors) and warns that small samples routinely yield untestable outcomes. The decision not to proceed was driven primarily by the inadequate sample (n=24) for the specific shaper question, which the historical failures (FAM:SF-APPS-090, FAM:SF-APPS-024) independently support. The positive connector finding does not overcome the power constraint for the narrower shaper test."
  },
  "testability": {
    "p_testable": 0.12,
    "blocking_constraints": [
      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "Only 24 shaper movers available. To detect a Spearman rho of 0.26 (CHT-057 effect) at 80% power, more than 100 units would be needed. The likelihood of obtaining a conclusive result is very low."
      },
      {
        "code": "EXPOSURE_SPARSITY",
        "text": "If cut-heavy and drive-heavy shapers are defined by extreme terciles or quartiles, the effective sample per group could be very small (e.g., 8-12 per group), making comparisons even more fragile."
      }
    ]
  },
  "prior_work": {
    "already_answered": "partly",
    "cited": [
      "FAM:SF-CHT-057"
    ],
    "summary": "FAM:SF-CHT-057 partly answered the question for connectors: cut-heavy connectors' roles travel better than drive-heavy ones. Our question replaces 'connectors' with 'shapers', a related but not identical role category. The prior work suggests the directional hypothesis is plausible but does not confirm it for shapers specifically."
  },
  "risks": [
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "n=24 is grossly underpowered for correlation or mean-difference tests at plausible effect sizes; any estimated effect would have wide error bars and be non-replicable."
    },
    {
      "code": "MEASURE_RELIABILITY",
      "text": "Shaper classification depends on structural influence residuals and play-type labels (CUT, DRIVE) that may be sensitive to pipeline version, classifier accuracy, and sample period; small sample amplifies misclassification noise."
    },
    {
      "code": "CONFOUNDING",
      "text": "Post-move portability is confounded by destination team system, minutes, role assignment, and health; with 24 units these cannot be adequately controlled."
    },
    {
      "code": "RTM_SELECTION",
      "text": "Selecting the most cut-heavy or drive-heavy shapers risks regression to the mean in their post-move metrics."
    },
    {
      "code": "MULTIPLE_TESTING",
      "text": "If many definitions of cut-heavy or portability are explored, the risk of false positives increases, yet correction would further erode power."
    }
  ],
  "predicted_outcome": {
    "supported": 0.07,
    "rejected": 0.08,
    "untestable": 0.70,
    "artifact": 0.03,
    "uncertain": 0.12
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "Difference in post-move portability (e.g., change in structural influence or teammate play-type displacement) between cut-heavy shapers and drive-heavy shapers, where shapers are players with above-team-median usage among low-usage, positive-residual-influence players, and 'cut-heavy' defined by a top-tercile cut initiation share in the season before the move.",
    "unit": "One player-team move (a unique player changing teams between consecutive seasons).",
    "sample": "All player-team moves identified in NBA 2022-23 through 2025-26 regular seasons where the player moves to a new team between seasons, played at least 20 games for both teams, and is classified as a shaper in the origin season. Current count 24 units.",
    "power": "Achievable power < 30% to detect rho=0.26; minimum detectable effect size would be rho > 0.55 at 80% power, which is implausible given CHT-057 effect sizes. The study is not viable without pooling or Bayesian prior-informed shrinkage.",
    "controls": "Destination team offensive scheme (e.g., share of cuts vs drives in team play-type mix), change in player usage, on-court stint context, injury status. With 24 units these cannot be entered as covariates without overfitting.",
    "falsification": "Placebo moves (players who stayed with the same team but are classified as shapers) to check whether 'portability' measures merely reflect within-team role changes. Also, test that pre-move drive share does not predict portability in a sample of role occupants (who should not show organizational portability).",
    "multiplicity": "Pre-registration of a single portability metric and a single cut/drive split definition to avoid specification fishing. All alternative definitions reported as robustness checks with no claim of significance.",
    "decision_rule": "Bayesian analysis with a skeptical prior informed by CHT-057; report posterior probability that the portability difference exceeds zero, with pre-registered region-of-practical-equivalence bounds. Decision based on whether 90% credible interval excludes zero.",
    "data_version": "NBA 2022-23 through 2025-26 regular seasons; per-game play-by-play and derived play-type initiation records as of 2026-08-08; shaper classification from the project's structural influence pipeline (latest stable release)."
  }
}}

